import React, { useState, useEffect, useRef } from 'react';
import { Message } from '../types';
import { startChat, sendMessageStream } from '../services/geminiService';

interface ChatInterfaceProps {
  isOpen: boolean;
  onClose: () => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ isOpen, onClose }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: "Hey! I'm Daniel's AI assistant. Ask me anything about his work, experience, or what he's listening to right now." }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen && !chatRef.current) {
      chatRef.current = startChat();
    }
  }, [isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    let assistantResponse = '';
    setMessages(prev => [...prev, { role: 'model', text: '' }]);

    const stream = sendMessageStream(chatRef.current, userMessage);

    for await (const chunk of stream) {
      assistantResponse += chunk;
      setMessages(prev => {
        const newMessages = [...prev];
        newMessages[newMessages.length - 1].text = assistantResponse;
        return newMessages;
      });
    }

    setIsTyping(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-xl flex justify-end">
      <div className="w-full lg:w-[450px] bg-[#0c0c0c] h-full flex flex-col border-l border-white/10 shadow-2xl relative">
        <div className="p-8 border-b border-white/10 flex justify-between items-center">
          <div>
            <h3 className="font-heading font-black text-2xl tracking-tighter">NEURAL CHAT</h3>
            <div className="flex items-center gap-2 mt-1">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
              <span className="text-[10px] font-bold tracking-widest text-white/40 uppercase">System Online</span>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-2 hover:bg-white/5 rounded-full transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 scroll-smooth">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`max-w-[85%] p-4 rounded-lg text-sm leading-relaxed ${
                msg.role === 'user' 
                  ? 'bg-white text-black font-bold' 
                  : 'bg-white/5 text-white/80 border border-white/10'
              }`}>
                {msg.text || (isTyping && idx === messages.length - 1 ? '...' : '')}
              </div>
              <span className="text-[10px] text-white/20 mt-2 font-bold uppercase tracking-widest">
                {msg.role === 'user' ? 'Daniel (Human)' : 'AI-DANIEL'}
              </span>
            </div>
          ))}
          {isTyping && messages[messages.length-1].text === '' && (
             <div className="flex flex-col items-start">
               <div className="bg-white/5 p-4 rounded-lg border border-white/10">
                 <div className="flex gap-1">
                   <div className="w-1 h-1 bg-white rounded-full animate-bounce"></div>
                   <div className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:0.2s]"></div>
                   <div className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:0.4s]"></div>
                 </div>
               </div>
             </div>
          )}
        </div>

        <div className="p-8 border-t border-white/10">
          <form onSubmit={handleSubmit} className="relative">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type your message..."
              className="w-full bg-white/5 border border-white/10 rounded-sm p-4 pr-12 text-sm focus:outline-none focus:border-white transition-colors"
            />
            <button 
              type="submit"
              className="absolute right-3 top-1/2 -translate-y-1/2 text-white/40 hover:text-white transition-colors"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
            </button>
          </form>
          <p className="mt-4 text-[10px] text-white/20 text-center uppercase tracking-widest">
            Powered by Gemini AI Neural Engine
          </p>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

