import React, { useState, useEffect, useRef } from 'react';
import { Message } from '../types';
import { startChat, sendMessageStream } from '../services/geminiService';

interface ChatInterfaceProps {
  isOpen: boolean;
  onClose: () => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ isOpen, onClose }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: "Hey! I'm Daniel's AI neural companion. Ask me anything about his projects on DanielCodeBlog or his tech stack." }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen && !chatRef.current) {
      chatRef.current = startChat();
    }
  }, [isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    let assistantResponse = '';
    setMessages(prev => [...prev, { role: 'model', text: '' }]);

    const stream = sendMessageStream(chatRef.current, userMessage);

    for await (const chunk of stream) {
      assistantResponse += chunk;
      setMessages(prev => {
        const newMessages = [...prev];
        newMessages[newMessages.length - 1].text = assistantResponse;
        return newMessages;
      });
    }

    setIsTyping(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-[#0F211D]/40 backdrop-blur-md flex justify-end">
      <div className="w-full lg:w-[500px] bg-[#FDFCF0] h-full flex flex-col border-l border-[#0F211D]/10 shadow-2xl relative">
        <div className="p-8 border-b border-[#0F211D]/10 flex justify-between items-center bg-[#FDFCF0]">
          <div>
            <h3 className="font-heading font-black text-3xl tracking-tighter text-[#0F211D]">NEURAL NODE</h3>
            <div className="flex items-center gap-2 mt-1">
              <span className="w-2 h-2 rounded-full bg-[#2D5A27] animate-pulse"></span>
              <span className="text-[10px] font-black tracking-widest text-[#0F211D]/40 uppercase">Connection Secured</span>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-3 bg-[#0F211D]/5 hover:bg-[#D4FF3F] rounded-full transition-all text-[#0F211D]"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 scroll-smooth">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`max-w-[85%] p-5 rounded-2xl text-sm leading-relaxed font-medium shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-[#0F211D] text-[#FDFCF0] rounded-tr-none' 
                  : 'bg-white text-[#0F211D] border border-[#0F211D]/10 rounded-tl-none'
              }`}>
                {msg.text || (isTyping && idx === messages.length - 1 ? 'Thinking...' : '')}
              </div>
              <span className="text-[9px] text-[#0F211D]/30 mt-2 font-black uppercase tracking-[0.2em]">
                {msg.role === 'user' ? 'YOU' : 'DANIEL_AI.V1'}
              </span>
            </div>
          ))}
        </div>

        <div className="p-8 bg-white border-t border-[#0F211D]/10">
          <form onSubmit={handleSubmit} className="relative">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask anything..."
              className="w-full bg-[#FDFCF0] border-2 border-[#0F211D]/5 rounded-xl p-5 pr-14 text-sm font-bold focus:outline-none focus:border-[#2D5A27] transition-all text-[#0F211D] placeholder:text-[#0F211D]/20"
            />
            <button 
              type="submit"
              className="absolute right-4 top-1/2 -translate-y-1/2 bg-[#0F211D] text-[#D4FF3F] p-2 rounded-lg hover:scale-110 transition-all"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
            </button>
          </form>
          <div className="mt-6 flex justify-center gap-8 opacity-40">
             <span className="text-[8px] font-black tracking-widest text-[#0F211D] uppercase">Gemini 3.0</span>
             <span className="text-[8px] font-black tracking-widest text-[#0F211D] uppercase">Tonik UI</span>
          </div>
        </div>
      </div>
    </div>
  );
};

