import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const VeoVideo: React.FC = () => {
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [needsKey, setNeedsKey] = useState(false);

  const checkKeyAndGenerate = async () => {
    setError(null);
    setLoading(true);

    try {
      // 1. Check if a key has been selected as per Veo requirements
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setNeedsKey(true);
        setLoading(false);
        return;
      }

      setNeedsKey(false);

      // 2. Create a new instance right before the call to ensure latest key is used
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: 'A cinematic, high-quality close up of dark green liquid ink swirling with electric lime glowing highlights, macro photography, slow motion, brutalist aesthetic, minimalist background',
        config: {
          numberOfVideos: 1,
          resolution: '1080p',
          aspectRatio: '9:16'
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        // Must append API key when fetching from the download link
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        if (!response.ok) throw new Error("Failed to download video");
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      } else {
        throw new Error("Video generation failed to return a link");
      }
    } catch (err: any) {
      console.error("Video generation failed:", err);
      // If permission is denied, prompt for key selection again
      if (err.message?.includes("permission") || err.status === 403 || err.status === 404) {
        setError("API Key requires paid billing or lacks permissions. Please select a valid key.");
        setNeedsKey(true);
      } else {
        setError("Something went wrong during generation. Please try again.");
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    checkKeyAndGenerate();
  }, []);

  const handleSelectKey = async () => {
    try {
      await window.aistudio.openSelectKey();
      // Assume success and proceed as per instructions
      checkKeyAndGenerate();
    } catch (e) {
      console.error("Failed to open key selector", e);
    }
  };

  if (needsKey) {
    return (
      <div className="w-full h-full bg-[#0F211D] flex flex-col items-center justify-center p-12 text-center space-y-8">
        <div className="w-16 h-16 border-4 border-[#D4FF3F]/20 border-t-[#D4FF3F] rounded-full animate-pulse"></div>
        <div className="space-y-4">
          <h3 className="text-xl font-heading font-black text-[#FDFCF0] tracking-tighter">VIDEO GENERATOR SETUP</h3>
          <p className="text-[10px] font-bold text-[#FDFCF0]/40 uppercase tracking-[0.2em] leading-relaxed max-w-xs mx-auto">
            Veo requires a paid API key for cinematic video generation. 
            {error && <span className="block text-[#D4FF3F] mt-2">{error}</span>}
          </p>
        </div>
        <button 
          onClick={handleSelectKey}
          className="bg-[#D4FF3F] text-[#0F211D] px-8 py-4 text-[10px] font-black uppercase tracking-[0.4em] hover:scale-105 transition-all shadow-[0_10px_30px_rgba(212,255,63,0.2)]"
        >
          SELECT API KEY
        </button>
        <a 
          href="https://ai.google.dev/gemini-api/docs/billing" 
          target="_blank" 
          rel="noopener noreferrer"
          className="text-[8px] font-bold text-[#FDFCF0]/20 underline tracking-widest hover:text-[#FDFCF0]/50 transition-colors"
        >
          LEARN ABOUT BILLING
        </a>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="w-full h-full bg-[#0F211D] flex flex-col items-center justify-center p-12 text-center">
        <div className="relative w-20 h-20 mb-10">
          <div className="absolute inset-0 border-2 border-[#D4FF3F]/10 rounded-full"></div>
          <div className="absolute inset-0 border-2 border-[#D4FF3F] border-t-transparent rounded-full animate-spin"></div>
        </div>
        <div className="space-y-4 animate-pulse">
           <p className="text-[10px] font-black uppercase tracking-[0.4em] text-[#D4FF3F]">Initializing Neural Motion...</p>
           <p className="text-[8px] font-bold text-[#FDFCF0]/30 uppercase tracking-[0.2em]">This may take a few minutes</p>
        </div>
      </div>
    );
  }

  if (error && !videoUrl) {
    return (
      <div className="w-full h-full bg-[#0F211D] overflow-hidden flex items-center justify-center relative">
        <img 
          src="https://images.unsplash.com/photo-1550684848-fac1c5b4e853?auto=format&fit=crop&q=80&w=1200" 
          className="w-full h-full object-cover grayscale opacity-20"
          alt="Backup visual"
        />
        <div className="absolute inset-0 flex flex-col items-center justify-center p-10 text-center">
           <p className="text-[10px] font-black text-[#D4FF3F] tracking-widest uppercase mb-4">Fallback Active</p>
           <button onClick={checkKeyAndGenerate} className="text-[8px] font-bold text-[#FDFCF0]/40 uppercase tracking-widest hover:text-[#D4FF3F]">Retry Generation</button>
        </div>
      </div>
    );
  }

  return (
    <video 
      src={videoUrl || ''} 
      autoPlay 
      loop 
      muted 
      playsInline 
      className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-1000"
    />
  );
};

