import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";

const VeoVideo: React.FC = () => {
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [needsKey, setNeedsKey] = useState(false);

  const checkKeyAndGenerate = async () => {
    setError(null);
    setLoading(true);

    try {
      // Access aistudio via window casting to avoid declaration conflicts.
      const hasKey = await (window as any).aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setNeedsKey(true);
        setLoading(false);
        return;
      }

      setNeedsKey(false);

      // Use process.env.API_KEY directly as a named parameter.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: 'A breathtaking cinematic macro shot of liquid obsidian and emerald glass shattering in slow motion, the fragments then reassembling in mid-air to form an abstract geometric structure. Radiant neon lime energy pulses through the fissures. High-fashion brutalist aesthetic, dark atmospheric background, hyper-realistic reflections, majestic and hypnotic movement.',
        config: {
          numberOfVideos: 1,
          resolution: '1080p',
          aspectRatio: '16:9'
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        if (!response.ok) throw new Error("Failed to download video");
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      } else {
        throw new Error("Video generation failed to return a link");
      }
    } catch (err: any) {
      console.error("Video generation failed:", err);
      if (err.message?.includes("permission") || err.status === 403) {
        setNeedsKey(true);
      } else {
        setError("Background loading failed.");
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    checkKeyAndGenerate();
  }, []);

  if (needsKey) {
    return (
      <div className="absolute inset-0 z-0 bg-[#0F211D] flex flex-col items-center justify-center p-12 text-center space-y-6">
        <div className="relative mb-4">
            <div className="w-16 h-16 border-2 border-[#D4FF3F]/20 rounded-full"></div>
            <div className="absolute inset-0 border-2 border-[#D4FF3F] border-t-transparent rounded-full animate-spin"></div>
        </div>
        <h3 className="text-xl font-heading font-black text-[#FDFCF0] tracking-tighter uppercase">Cinematic Background Inactive</h3>
        <button 
          onClick={() => (window as any).aistudio.openSelectKey().then(checkKeyAndGenerate)}
          className="bg-[#D4FF3F] text-[#0F211D] px-10 py-4 text-[11px] font-black uppercase tracking-[0.4em] hover:scale-105 transition-all shadow-[0_15px_40px_rgba(212,255,63,0.15)]"
        >
          SELECT API KEY TO GENERATE
        </button>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="absolute inset-0 z-0 bg-[#0F211D] flex flex-col items-center justify-center p-12 text-center">
        <div className="w-10 h-10 border-2 border-[#D4FF3F]/10 border-t-[#D4FF3F] rounded-full animate-spin mb-6"></div>
        <div className="space-y-2">
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-[#D4FF3F]">Orchestrating Visuals...</p>
            <p className="text-[8px] font-bold uppercase tracking-[0.3em] text-[#FDFCF0]/30 italic">Dreaming up liquid emerald & Obsidian</p>
        </div>
      </div>
    );
  }

  return (
    <div className="absolute inset-0 z-0 overflow-hidden bg-[#0F211D]">
      {/* Gradient mask for seamless blend */}
      <div className="absolute inset-0 bg-gradient-to-r from-[#FDFCF0] via-[#FDFCF0]/90 to-transparent z-10 hidden lg:block"></div>
      <div className="absolute inset-0 bg-[#FDFCF0]/90 z-10 lg:hidden block"></div>

      {videoUrl ? (
        <video 
          src={videoUrl} 
          autoPlay 
          loop 
          muted 
          playsInline 
          className="w-full h-full object-cover grayscale opacity-50 group-hover:opacity-70 transition-all duration-1000 scale-105"
        />
      ) : (
          <div className="w-full h-full bg-[#0F211D] opacity-20"></div>
