import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

const ThreeBackground: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    // Scene Setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    containerRef.current.appendChild(renderer.domElement);

    // Geometry - Floating "Brutalist" Neural Mesh
    const geometry = new THREE.IcosahedronGeometry(1, 1);
    const wireframeMaterial = new THREE.MeshBasicMaterial({ 
      color: 0x0F211D, 
      wireframe: true, 
      transparent: true, 
      opacity: 0.1 
    });
    const pointsMaterial = new THREE.PointsMaterial({
      color: 0xD4FF3F,
      size: 0.02,
    });

    const mesh = new THREE.Mesh(geometry, wireframeMaterial);
    const points = new THREE.Points(geometry, pointsMaterial);

    const group = new THREE.Group();
    group.add(mesh);
    group.add(points);
    scene.add(group);

    camera.position.z = 2.5;

    // Interactivity
    let mouseX = 0;
    let mouseY = 0;
    let targetX = 0;
    let targetY = 0;

    const handleMouseMove = (event: MouseEvent) => {
      mouseX = (event.clientX / window.innerWidth) - 0.5;
      mouseY = (event.clientY / window.innerHeight) - 0.5;
    };

    window.addEventListener('mousemove', handleMouseMove);

    // Animation Loop
    const animate = () => {
      requestAnimationFrame(animate);

      // Smooth Lerp for interactive movement
      targetX += (mouseX - targetX) * 0.05;
      targetY += (mouseY - targetY) * 0.05;

      group.rotation.y += 0.002;
      group.rotation.x += 0.001;

      group.position.x = targetX * 0.5;
      group.position.y = -targetY * 0.5;

      renderer.render(scene, camera);
    };

    animate();

    // Resize
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', handleResize);
      if (containerRef.current) {
        containerRef.current.removeChild(renderer.domElement);
      }
    };
  }, []);

  return (
    <div ref={containerRef} className="absolute inset-0 z-0 pointer-events-none opacity-40 lg:opacity-60" />
  );
};

