import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

const NeuralCore: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    containerRef.current.appendChild(renderer.domElement);

    // Geometry - Morphing "Glass" Sphere
    const geometry = new THREE.IcosahedronGeometry(1.2, 32);

    // Using a custom material approach to mimic a high-end 3D render look
    const material = new THREE.MeshPhongMaterial({
      color: 0x0F211D,
      specular: 0xD4FF3F,
      shininess: 100,
      flatShading: false,
      wireframe: false,
      transparent: true,
      opacity: 0.9,
    });

    const wireMat = new THREE.MeshBasicMaterial({
        color: 0xD4FF3F,
        wireframe: true,
        transparent: true,
        opacity: 0.05
    });

    const mesh = new THREE.Mesh(geometry, material);
    const wire = new THREE.Mesh(geometry, wireMat);
    wire.scale.setScalar(1.02);

    const group = new THREE.Group();
    group.add(mesh);
    group.add(wire);
    scene.add(group);

    // Lights
    const light1 = new THREE.DirectionalLight(0xD4FF3F, 1);
    light1.position.set(5, 5, 5);
    scene.add(light1);

    const light2 = new THREE.PointLight(0xFFFFFF, 0.5);
    light2.position.set(-5, -5, 5);
    scene.add(light2);

    camera.position.z = 3;

    // Displacement mapping simulation
    const initialPositions = geometry.attributes.position.array.slice();

    let mouseX = 0;
    let mouseY = 0;
    let targetX = 0;
    let targetY = 0;

    const handleMouseMove = (event: MouseEvent) => {
      mouseX = (event.clientX / window.innerWidth) - 0.5;
      mouseY = (event.clientY / window.innerHeight) - 0.5;
    };

    window.addEventListener('mousemove', handleMouseMove);

    const animate = (time: number) => {
      requestAnimationFrame(animate);

      // Morphing effect
      const positions = geometry.attributes.position.array;
      for (let i = 0; i < positions.length; i += 3) {
        const x = initialPositions[i];
        const y = initialPositions[i + 1];
        const z = initialPositions[i + 2];

        const noise = Math.sin(x * 2 + time * 0.001) * 0.1 + 
                      Math.cos(y * 2 + time * 0.001) * 0.1;

        positions[i] = x * (1 + noise);
        positions[i+1] = y * (1 + noise);
        positions[i+2] = z * (1 + noise);
      }
      geometry.attributes.position.needsUpdate = true;

      // Interaction lerp
      targetX += (mouseX - targetX) * 0.05;
      targetY += (mouseY - targetY) * 0.05;

      group.rotation.y += 0.005;
      group.position.x = targetX * 1.5;
      group.position.y = -targetY * 1.5;

      renderer.render(scene, camera);
    };

    animate(0);

    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', handleResize);
      if (containerRef.current) containerRef.current.removeChild(renderer.domElement);
    };
  }, []);

  return <div ref={containerRef} className="absolute inset-0 z-0 pointer-events-none" />;
};

