  const requestRef = useRef<number | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    containerRef.current.appendChild(renderer.domElement);

    const geometry = new THREE.IcosahedronGeometry(1.6, 4);
    const material = new THREE.MeshPhongMaterial({
      color: 0x0F211D,
      specular: 0xD4FF3F,
      shininess: 150,
      transparent: true,
      opacity: 0.9,
    });

    const wireMat = new THREE.MeshBasicMaterial({
        color: 0xD4FF3F,
        wireframe: true,
        transparent: true,
        opacity: 0.05
    });

    const mesh = new THREE.Mesh(geometry, material);
    const wire = new THREE.Mesh(geometry, wireMat);
    wire.scale.setScalar(1.02);

    const group = new THREE.Group();
    group.add(mesh);
    group.add(wire);
    scene.add(group);

    const light1 = new THREE.DirectionalLight(0xD4FF3F, 2);
    light1.position.set(5, 5, 5);
    scene.add(light1);

    const light2 = new THREE.PointLight(0xFFFFFF, 0.8);
    light2.position.set(-5, -5, 5);
    scene.add(light2);

    camera.position.z = 5;

    const initialPositions = new Float32Array(geometry.attributes.position.array);

    let mouseX = 0, mouseY = 0, targetX = 0, targetY = 0;

    const handleMouseMove = (e: MouseEvent) => {
      mouseX = (e.clientX / window.innerWidth) - 0.5;
      mouseY = (e.clientY / window.innerHeight) - 0.5;
    };

    const handleScroll = () => {
      scrollYRef.current = window.scrollY;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('scroll', handleScroll, { passive: true });

    const animate = (time: number) => {
      requestRef.current = requestAnimationFrame(animate);

      const positions = geometry.attributes.position.array;
      for (let i = 0; i < positions.length; i += 3) {
        const x = initialPositions[i];
        const y = initialPositions[i + 1];
        const z = initialPositions[i + 2];
        const noise = Math.sin(x * 1.2 + time * 0.001) * 0.2 + Math.cos(y * 1.2 + time * 0.001) * 0.2;
        positions[i] = x * (1 + noise);
        positions[i+1] = y * (1 + noise);
        positions[i+2] = z * (1 + noise);
      }
      geometry.attributes.position.needsUpdate = true;

      targetX += (mouseX - targetX) * 0.05;
      targetY += (mouseY - targetY) * 0.05;

      group.rotation.y += 0.004;
      group.rotation.x += 0.001;

      const scrollFactor = scrollYRef.current * 0.002;
      group.position.x = targetX * 1.5;
      group.position.y = (-targetY * 1.5) - (scrollFactor * 1.2);

      const scale = Math.max(0.6, 1.2 - (scrollFactor * 0.15));
      group.scale.setScalar(scale);

      renderer.render(scene, camera);
    };

    requestRef.current = requestAnimationFrame(animate);

    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      if (requestRef.current !== null) cancelAnimationFrame(requestRef.current);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('resize', handleResize);

      if (containerRef.current && renderer.domElement) {
        containerRef.current.removeChild(renderer.domElement);
      }

      geometry.dispose();
      material.dispose();
      wireMat.dispose();
      renderer.dispose();
    };
  }, []);

  return <div ref={containerRef} className="fixed inset-0 z-0 pointer-events-none" />;
};

