const MinimizeProjectCard: React.FC<{ project: any; index: number }> = ({ project, index }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [opacity, setOpacity] = useState(1);

  useEffect(() => {
    const handleScroll = () => {
      if (!cardRef.current) return;

      const rect = cardRef.current.getBoundingClientRect();
      const viewportHeight = window.innerHeight;

      // Calculate how much of the card has passed the top of the viewport
      // As it scrolls up, the scale should decrease slightly like iOS minimizing
      if (rect.top < 100) {
        const progress = Math.min(Math.max((100 - rect.top) / viewportHeight, 0), 1);
        const newScale = 1 - (progress * 0.15); // Scale down to 0.85
        const newOpacity = 1 - (progress * 0.3); // Fade out slightly
        setScale(newScale);
        setOpacity(newOpacity);
      } else {
        setScale(1);
        setOpacity(1);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div 
      ref={cardRef}
      className="sticky top-24 w-full px-4 md:px-10 h-[85vh] flex items-center justify-center pointer-events-none"
      style={{
        zIndex: index + 1,
      }}
    >
      <div 
        className="relative w-full max-w-[1400px] h-full rounded-[2.5rem] md:rounded-[4rem] overflow-hidden bg-[#0F211D] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.3)] pointer-events-auto cursor-pointer transition-transform duration-300 ease-out origin-center"
        style={{
          transform: `scale(${scale})`,
          opacity: opacity,
        }}
        onClick={() => window.open(project.link, '_blank')}
      >
        {/* Project Image - Immersive background */}
        <div className="absolute inset-0 w-full h-full">
          <img 
            src={project.imageUrl} 
            alt={project.title}
            className="w-full h-full object-cover grayscale opacity-60 hover:grayscale-0 hover:opacity-100 transition-all duration-1000 scale-105 hover:scale-100"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-[#0F211D] via-[#0F211D]/20 to-transparent"></div>
        </div>

        {/* Content Overlay */}
        <div className="absolute bottom-0 left-0 w-full p-8 md:p-20 flex flex-col md:flex-row items-end justify-between gap-10">
          <div className="space-y-6 max-w-2xl">
            <div className="flex items-center gap-4">
