                </a>
            ))}
            <div className={`pt-12 transition-all duration-1000 delay-500 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`}>
                <a 
                    href="#contact" 
                    onClick={(e) => handleNavClick(e, '#contact')}
                    className="inline-block px-14 py-6 bg-[#D4FF3F] text-[#0F211D] rounded-full font-black uppercase tracking-widest text-xs hover:scale-110 transition-transform shadow-2xl"
                >
                    Start a Project
                </a>
            </div>
        </div>
      </div>
    </>
  );
};

export default Header;

import React, { useState } from 'react';

const ContactForm: React.FC = () => {
  const [formState, setFormState] = useState<'idle' | 'submitting' | 'success'>('idle');
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormState('submitting');

    // Simulation of transmission
    await new Promise(resolve => setTimeout(resolve, 1500));

    setFormState('success');
    setFormData({ name: '', email: '', message: '' });
  };

  if (formState === 'success') {
    return (
      <div className="bg-[#D4FF3F] p-12 md:p-20 rounded-[3rem] text-[#0F211D] animate-in zoom-in duration-500 shadow-2xl border border-white/20">
        <h3 className="text-5xl md:text-7xl font-heading font-black tracking-tighter leading-none mb-8">MESSAGE <br/>RECEIVED.</h3>
        <p className="text-xl font-bold mb-10 opacity-80">The signal has been transmitted. I'll reach out within 24 hours.</p>
        <button 
          onClick={() => setFormState('idle')}
          className="px-10 py-4 bg-[#0F211D] text-[#FDFCF0] rounded-full font-black uppercase tracking-widest text-xs hover:scale-105 transition-transform"
        >
          Send Another
        </button>
      </div>
    );
  }

  return (
    <div className="relative p-8 md:p-12 lg:p-16 rounded-[3rem] bg-white/5 backdrop-blur-3xl border border-white/10 shadow-[0_32px_64px_-16px_rgba(0,0,0,0.5)] overflow-hidden group">
      {/* Decorative gradient blur in background of the form */}
      <div className="absolute -top-24 -right-24 w-64 h-64 bg-[#D4FF3F]/5 blur-[120px] rounded-full pointer-events-none group-hover:bg-[#D4FF3F]/10 transition-colors duration-1000"></div>

      <form onSubmit={handleSubmit} className="relative z-10 space-y-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-3">
            <label className="text-[10px] font-black uppercase tracking-[0.4em] text-[#D4FF3F]/40 ml-2">Your Name</label>
            <input
              required
              type="text"
              placeholder="John Doe"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 text-lg font-bold focus:outline-none focus:border-[#D4FF3F] focus:bg-white/10 transition-all placeholder:text-white/5"
            />
          </div>
          <div className="space-y-3">
            <label className="text-[10px] font-black uppercase tracking-[0.4em] text-[#D4FF3F]/40 ml-2">Your Email</label>
            <input
              required
              type="email"
              placeholder="hello@world.com"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 text-lg font-bold focus:outline-none focus:border-[#D4FF3F] focus:bg-white/10 transition-all placeholder:text-white/5"
            />
          </div>
        </div>

        <div className="space-y-3">
          <label className="text-[10px] font-black uppercase tracking-[0.4em] text-[#D4FF3F]/40 ml-2">Your Message</label>
          <textarea
            required
            rows={4}
            placeholder="What's on your mind?"
            value={formData.message}
            onChange={(e) => setFormData({ ...formData, message: e.target.value })}
            className="w-full bg-white/5 border border-white/10 rounded-2xl py-5 px-6 text-lg font-bold focus:outline-none focus:border-[#D4FF3F] focus:bg-white/10 transition-all placeholder:text-white/5 resize-none"
          />
        </div>

        <div className="pt-4">
          <button
            type="submit"
            disabled={formState === 'submitting'}
            className="group/btn relative flex items-center justify-between w-full p-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-full transition-all duration-500 disabled:opacity-50"
          >
            <span className="ml-8 text-[10px] font-black uppercase tracking-[0.5em] text-[#D4FF3F]">
              {formState === 'submitting' ? 'UPLOADING...' : 'SEND SIGNAL'}
            </span>
            <div className="w-16 h-16 rounded-full bg-[#D4FF3F] flex items-center justify-center text-[#0F211D] transition-transform duration-500 group-hover/btn:scale-95 group-hover/btn:rotate-45">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                <line x1="7" y1="17" x2="17" y2="7"></line>
                <polyline points="7 7 17 7 17 17"></polyline>
              </svg>
            </div>
          </button>
        </div>
      </form>
    </div>
  );
};

export default ContactForm;
